 .hold {
  width: 0;
  height: 0;
  position: absolute;
  top: 0;
  right: 0; 
  
}

.has-sub .hold::after {
  display: block;
  position: absolute;
  content: "";
  width: 10px;
  height: 10px;
  right: 20px;
  z-index: 5;   
  top:25px;
  background:#fff url('../images/sub/lnb-on.png') no-repeat;
}
#lnbmenu > ul > li.open .hold::after {
  background:#1764c4 url('../images/sub/lnb-off.png') no-repeat; 
}
#lnbmenu > ul > li.has-sub:hover .hold::after{
  background:#1764c4 url('../images/sub/lnb-off.png') no-repeat; 
}

#lnbmenu > ul > li > a:hover span::after,
#lnbmenu > ul > li.active > a > span::after,
#lnbmenu > ul > li.open .hold::after{
  display: block;
  position: absolute;
  content: "";
  width: 10px;
  height: 10px;
  right: 20px;
  z-index: 5;  
  top: 25px;  
}
 
#lnbmenu ul ul li a {
  cursor: pointer;
  padding: 20px;
  z-index: 1;
  text-decoration: none;
  font-size: 18px;
  color: #555;
  background: #f3f5f9;
  margin-bottom:2px;;
  border-radius: 10px;
}
#lnbmenu ul ul li:hover > a,
#lnbmenu ul ul li.open > a,
#lnbmenu ul ul li.active > a {
  color: #1764c4;
}
#lnbmenu ul ul li:first-child > a {
  box-shadow: none;
}
#lnbmenu ul ul ul li:first-child > a {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
#lnbmenu ul ul ul li a {
  padding-left: 30px;
 
}
#lnbmenu > ul > li > ul > li:last-child > a,
#lnbmenu > ul > li > ul > li.last > a {
  border-radius: 10px 10px 0 0;
  border-bottom: 1px solid #e2e2e2;
}
#lnbmenu > ul > li > ul > li.open:last-child > a,
#lnbmenu > ul > li > ul > li.last.open > a {
  border-bottom: 1px solid #32373e;
}
#lnbmenu > ul > li > ul > li.open:last-child > ul > li:last-child > a {
  border-bottom: 0;
}
#lnbmenu ul ul li > a::after {
  display: block;
  position: absolute;
  content: "";
  width: 6px;
  height: 6px;
  right: 20px;
  z-index: 5;
  top: 25px;
  border-top: 2px solid #f3f5f9;
  border-left: 2px solid #f3f5f9;
  -webkit-transform: rotate(135deg);
  -moz-transform: rotate(135deg);
  -ms-transform: rotate(135deg);
  -o-transform: rotate(135deg);
  transform: rotate(135deg);
 
}
#lnbmenu ul ul li.active > a::after,
#lnbmenu ul ul li.open > a::after,
#lnbmenu ul ul li > a:hover::after {
  border-color: #1764c4;
}
