/* FORM
/* –––––––––––––––––––––––––––––––––––––––––––––––––– */
.form-input-check {display: flex; flex-wrap: wrap;}
.checkbox,
.radio {
    position: relative; 
    display: inline-block; 
    margin:8px 0 8px; 
    text-align: left; 
    color:#2B2A29; 
    font-size: 16px; 
    line-height: 1.3; 
    cursor: pointer
}
.checkbox input[type="checkbox"],
.radio input[type="radio"] {
    display: inline-block; 
    vertical-align: middle; 
    opacity: 0;
}
.checkbox input[type="checkbox"],
.radio input[type="radio"],
.checkbox label::before,
.radio label::before {
    width: 18px; 
    height: 18px; 
    position: absolute; 
    left: 0; top: 50%; 
    transform: translateY(-50%);
}
.checkbox label {
    display: flex;
    position: relative; 
    min-height: 18px; 
    padding: 3px 0 0 24px; 
    cursor: pointer; 
    margin-bottom: 0;
}
.checkbox label::before {
    content: ''; 
    border: 1px solid #D3D3D3;
    background:#fff; 
    border-radius: 3px; 
    transition: all 0.1s; 
    width: 18px; 
    height: 18px; 
    
}
.checkbox svg {
    position: absolute; 
    top: 50%; left: 4px; 
    width: 10px; 
    height: 12px; 
    margin-top:-6px; 
    pointer-events: none;
}
.checkbox svg path {
    stroke: #fff; 
    stroke-width: 14px; 
    fill: none; 
    stroke-dasharray: 240; 
    stroke-dashoffset: 240; 
    transition: stroke-dashoffset 0.2s 0s ease-in;
}

.checkbox input[type="checkbox"]:checked + label::before {
    border-color: #1764c4; 
    background:#1764c4;
}
.checkbox input[type="checkbox"]:checked ~ svg path { 
    stroke-dashoffset: 0;
 }


.radio label {
    display: flex; 
    position: relative; 
    min-height: 20px; 
    padding: 3px 0 0 22px; 
    cursor: pointer; 
    margin-bottom: 0;
}
.radio label::before {
    content: ''; 
    border: 1px solid #D3D3D3; 
    border-radius: 50%; 
    transition: all 0.3s; 
    width: 18px; 
    height: 18px;
}
.radio svg {
    position: absolute; 
    top: 50%; left: 4px;
     width: 10px; 
     height: 10px; 
     margin-top: -5px; 
     pointer-events: none;
    }
.radio svg circle {
    fill: #fff; 
    transition: all 0.2s; 
    opacity: 0;
}

.radio input[type="radio"]:checked + label::before {
    border-color: #1764c4;
    background:#1764c4;
}
.radio input[type="radio"]:checked ~ svg circle {
    opacity: 1;
}

.checkbox ~ .checkbox,
.radio ~ .radio {margin-left: 12px;}

.switch {
    position:relative; 
    display:inline-block; 
    width:52px; 
    height:28px;
}
.switch input {
    opacity:0; 
    width:0; 
    height:0;
}
.switch-ctl {
    position:absolute; 
    cursor:pointer; 
    top:0; left:0; right:0; bottom:0; 
    background-color:#d0d0d0; 
    -webkit-transition:.4s; 
    transition:.4s; 
    border-radius:18px;
}
.switch-ctl:after {
    position:absolute; 
    content:""; 
    height:26px; 
    width:26px; 
    left:1.4px;
    bottom:1px; 
    background-color:white; 
    -webkit-transition:.4s; 
    transition:.4s; 
    border-radius:50%;
}
.switch input:checked + .switch-ctl {
    background-color:#1764c4;
}
.switch input:focus + .switch-ctl {
    -webkit-box-shadow:2px 3px 5px 0 rgba(0,0,0,0.1); 
    box-shadow:2px 3px 5px 0 rgba(0,0,0,0.1);
}
.switch input:checked + .switch-ctl:after {
    -webkit-transform:translateX(23.6px); 
    transform:translateX(23.6px);
}
.buttons-group-radio {
    position: relative; 
    display: flex;
}
.buttons-group-radio .radio-button ~ .radio-button {
    margin-left: -1px;
}
.buttons-group-radio .radio-button:first-child label {
    border-radius: 6px 0 0 6px;
}
.buttons-group-radio .radio-button:last-child label {
    border-radius: 0 6px 6px 0;
}
.buttons-group-radio .radio-button {
    position: relative; 
    display: inline-block; 
    background: #fff; 
    text-align: left; 
    color:#2B2A29; 
    font-size: 16px; 
    line-height: 1.3; 
    cursor: pointer;
}
.buttons-group-radio .radio-button input[type="radio"] {
    display: inline-block; 
    vertical-align: middle; 
    opacity: 0;
}
.buttons-group-radio .radio-button input[type="radio"] {
    width: 24px; 
    height: 24px; 
    position: absolute; 
    left: 0; top: 50%; 
    transform: translateY(-50%);
}
.buttons-group-radio .radio-button label {
    display: flex; 
    position: relative; 
    padding: 11px 19px; 
    border: 1px solid #E6E3E1; 
    line-height: 20px; 
    cursor: pointer;
}
