    user-select: none; 
}

/* 기본 라디오 버튼 숨기기 */
/*.radio_box input[type="radio"] { 
    display: none;
}*/
#contents input[type="radio"] { 
    width:20px;height:20px;vertical-align:middle;margin-top:-1px
}
#contents input[type="checkbox"] { 
    width:20px;height:20px;vertical-align:middle;margin-top:-1px
}
/* 선택되지 않은 라디오 버튼 스타일 꾸미기 */
.on { 
    width: 20px; 
    height: 20px; 
    background: #fff;
    border:1px #ddd solid; 
    border-radius: 50%; 
    position: absolute; 
    top: 0px; 
    left: 0; 
}
.on.top5 { 
    top: 5px;
}
/* 선택된 라디오 버튼 스타일 꾸미기 */

.radio_box input[type="radio"]:checked + .on { 
    background: #1764c4;
    border:1px #1764c4 solid
 }
.on:after { 
    content: ""; 
    position: absolute; 
    display: none; 
}
.radio_box input[type="radio"]:checked + .on:after { 
    display: block; 
}
.on:after { 
    width: 8px; 
    height: 8px; 
    background: #fff; 
    border-radius: 50%; 
    position: absolute; 
    left: 5px; 
    top: 5px; 
}
