/* base table - 가로스크롤 있는 테이블*/
.bsTable {
    width: 100%;
    overflow-x: scroll;
    padding-bottom:5px;
}
.bsTable::-webkit-scrollbar {
    height: 8px;
    
  }
.bsTable::-webkit-scrollbar-thumb {
    background-color: #dedede;
    border-radius: 50px;
}
.bsTable::-webkit-scrollbar-track {
    background-color: #f6f6f6;
    border:1px #dedede solid;
    border-radius: 50px;
}
.bsTable table {
    width: 1500px;
    border-collapse: separate;
    border-spacing: 0;
}
.bsTable table thead tr th {
   border-top:1px #ddd solid;
   border-bottom:1px #ddd solid;
   border-right:1px #ddd solid;
   background-color:#f9f9f9;
   font-size: 18px;
   font-weight: 600;
   color:#222;
   text-align: center;
   padding:15px 0;
}
.bsTable table thead tr th:last-child {
    border-right:0px
}
.bsTable table th:first-child {
    position: -webkit-sticky; 
    position: sticky; 
    left: 0; 
    border-right:1px #ddd solid;
    background-color: #f9f9f9;
}

.bsTable table tbody tr th {
    border-right:1px #ddd solid;
}
.bsTable table tbody th:first-child {
    background-color: #fff;
    position: -webkit-sticky; 
    position: sticky; 
    left: 0; 
}
.bsTable table tbody tr th,
.bsTable table tbody tr td {
    font-size: 16px;
    padding:15px 10px;
    text-align: center;
    border-bottom:1px #ddd solid;
    background-color: #fff;
}

.bsTable table tbody tr td.tb-bd {
    border-right:1px #ddd solid;
}




