.setting-btnarea {
    width:100%;
    border-top:1px #e4e4e4 dashed;
    display: flex;
    justify-content: center;
    padding-top:20px;
    margin-top:10px
}


/* 생활안전점검 리스트 하단 버튼 */
.survey-btnarea {
	text-align:center;
	width:100%;
}
.survey-btnarea a {
	margin:0 2px;
}

/* 개인정보처리방침 */
.priv-link {
	margin-top:20px;
}
.priv-link li {
    box-sizing: border-box;
    padding: 15px 30px 15px 15px;
    border: 1px #dfdfdf solid;
    font-size: 16px;
    font-weight: 600;
    border-radius: 10px;
    margin-bottom:10px;
    color: #555;
    background: #fff url(../images/sub/l-link.png) no-repeat 96% 20px;
    transition: 0.3s;
}
.priv-link li a{
	display:block
}
.priv-link li:hover {
	background:#f9f9f9 url(../images/sub/l-link.png) no-repeat 96% 20px;;
	box-shadow: 2px 3px 5px rgba(0, 0, 0, 0.08);
}


.privacy-list {
	margin-top:20px;
}
.privacy-list li {
    box-sizing: border-box;
    padding: 15px 30px 15px 15px;
    border: 1px #dfdfdf solid;
    font-size: 16px;
    font-weight: 600;
    border-radius: 10px;
    margin-bottom:10px;
    color: #555;
    background:#fff;
    transition: 0.3s;
}
.privacy-list li a{
	display:block
}
.privacy-list li:hover {
	background:#f9f9f9;
	box-shadow: 2px 3px 5px rgba(0, 0, 0, 0.08);
}

.privacy-btn {
    padding:7px 12px;
    font-size: 14px;
    color:#666;
    font-weight: 500;
    border:1px #ddd solid;
    border-radius:5px;
    transition:0.3s
}
.privacy-btn:hover {
    border:1px #bbb solid;
    color:#555;
    border-radius:5px;
    margin-top:3px;
    box-shadow: 2px 3px 5px rgba(0, 0, 0, 0.08);
}
.btn-pdown {
    height: 30px;
    line-height: 30px;
    background: #fff url('../images/sub/btn-down.png') no-repeat 95% 8px;
    background-size:10px;
    border-radius: 10px;
    color:#666;
    font-weight: 500;
    font-size: 14px;
    padding: 0 30px 0 10px;
    margin-top:2px;
    transition: 0.3s;
}
.btn-pdown:hover {
    background: #fff url('../images/sub/btn-down.png') no-repeat 95% 10px;
    background-size:10px;
    color:#222;
}

.priv-dot {
	background: url('../images/sub/btn-arr.png') no-repeat 0 7px;
	padding-left:13px;
}

.priv-list {
	padding-left:0px;
}
.priv-list li{
	font-size:18px;
	padding-bottom:10px;
	color:#222;
}
.priv-list li:last-child {
	padding-bottom:0;
}
.priv-slist {
	padding:0px 0 0px 15px;
}
.priv-slist li{
	font-size:16px;
	color:#222;
	padding:3px 0 10px 3px
}
.priv-slist li:last-child {
	padding-bottom:0;
}


@media all and (max-width:1500px) { 
    
    /* 재난현황 */
    .situation-cateinner {
        width: 100%;
        margin:0 auto;
        padding:0 2%;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .slider1 {
        width: 100%;
        max-width: 100%;
        height: 130px;
        margin: 0 auto;
        display: flex;
        flex-direction: row;
        justify-content: center;
        align-items: center;

    }
    .slider-wrapper {
        width: 90%;
        height: 130px;
        overflow: hidden;
        text-align: center;
    }
    .situation-content {
        width: 100%;
        margin:2% auto;
        padding:0 2%;
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
    }
    .situation-leftarea {
        width: 53%;
        margin-right:2%;        
    }
    .current-content {
        border:1px #d0d0d0 solid;
        box-shadow: 2px 3px 3px rgba(0, 0, 0, 0.05);
        border-radius: 20px;
        margin-bottom:0px;
        height: 330px;
        box-sizing: border-box;
        padding:30px;
        
    }
    .textmessage-content {
        margin-top:4%;
        border:1px #d0d0d0 solid;
        box-shadow: 2px 3px 3px rgba(0, 0, 0, 0.05);
        border-radius: 20px;
        height: 310px;
        box-sizing: border-box;
        padding:30px;
    }
    .situation-maparea {
        border:1px #d0d0d0 solid;
        box-shadow: 2px 3px 3px rgba(0, 0, 0, 0.05);
        border-radius: 20px;
        width: 45%;
        height: 660px;
        text-align: center;
        overflow: hidden;
    }
    .situation-infoarea {
        width: 100%;
        margin-top:2%;
        
    }
    
    .guideline-left {
        width: 53%;
        display: inline-block;
        border:1px #d0d0d0 solid;
        box-shadow: 2px 3px 3px rgba(0, 0, 0, 0.05);
        border-radius: 20px;
        padding:30px;
        margin-right:2%;
        height: 250px;
    }
    .around-facilities {
        width: 45%;
    }
    .around-faclist {
        border:1px #d0d0d0 solid;
        border-right:0px;
        box-shadow: 2px 3px 3px rgba(0, 0, 0, 0.05);
        width: 50%;
        height: 250px;
        border-radius: 20px 0 0 20px;
        overflow: hidden;
    }
    .around-safelist {
        border:1px #bdcfe1 solid;
        box-shadow: 2px 3px 3px rgba(0, 0, 0, 0.05);
        border-radius: 0 20px 20px 0;
        width: 50%;
        height: 250px;
        overflow: hidden;
    }


    /* 웹접근성 */
    .webaccess-box {
        background: #f5f5f5 url('../images/sub/webaccess-bg.png') no-repeat 100% 100%;
        border-radius: 20px;
        border:1px #dedede solid;
        box-shadow: 3px 0 7px rgba(0, 0, 0, 0.08);
        padding:35px 450px 35px 35px
    }
    .webaccess-box h3 {
        font-size: 30px;
        color:#222;
        font-weight: 700;
        margin-bottom:20px;
    }

    .webaccess-box p {
        font-size: 16px;
        color:#666;
    }
    .webaccess-box p span {
        font-weight: 600;
    }
    .web-accesslist {
        background-color: #f8f8f8;
        border:1px #f0f0f0 solid;
        border-radius: 10px;
        padding:30px;
        margin-bottom:5px;
        display: flex;
        flex-wrap: wrap;
    }
    .web-accesslist span {
        display: block;
        background-color: #1764c4;
        width: 70px;
        height: 70px;
        line-height: 70px;
        text-align: center;
        border-radius: 50%;
        margin-right:35px
    }
    .web-text h4 {
        color:#1764c4;
        font-size: 20px;
        font-weight: 600;
        padding-bottom:5px
    }
    .web-textlist li {
        background: url('../images/sub/p-slist.png') no-repeat 0 13px;
        padding: 5px 10px;
    }

    .web-linklist li {
        display: inline-block;
        background-color: #fff;
        border:1px #c8c8c8 solid;
        box-shadow: 3px 0 5px rgba(0, 0, 0, 0.12);
        border-radius: 50px;
        height: 46px;
        line-height: 46px;
        padding:0 20px;
        font-size: 18px;
        font-weight: 600;
        color:#222;
        text-align: center;
        margin-right:5px;
        margin-bottom:10px
    }

    /* Q&A */
