@media all and (max-width:1450px) {
    .linksite-list {
        width: 100%;
        display: flex;
        flex-wrap: wrap;
        gap:10px
    }
    .linksite-list li {
        width: 32.5%;
        box-sizing: border-box;
        padding:15px 30px 15px 15px;
        border:1px #dfdfdf solid;
        font-size: 17px;
        font-weight: 600;
        border-radius: 10px;
        color:#555;
        background: #fff url('../images/sub/l-link.png') no-repeat 94% 20px;
        transition: 0.3s;
    }
