        padding:5px 15px 5px 40px;
        border-radius: 80px;
        margin-bottom:10px
    }
    .insurance-list ul li .insur-button {
        background: url('../images/sub/dot.png') no-repeat 0% 50%; 
        padding:5px 0px 5px 10px;
