/* paging */

/* pagination
/* –––––––––––––––––––––––––––––––––––––––––––––––––– */
.paging {
    display: flex; 
    align-items: center; 
    justify-content: center; 
    margin-top: 20px; 
    color:#666;
    font-size: 16px;
}
.paging a,
.paging button {
    width: 34px; 
    height: 34px; 
    border:1px #ddd solid;
    text-align:center; 
    line-height: 1; 
    text-decoration: none; 
    cursor: pointer;
    border-radius: 3px; 
    letter-spacing:normal; 
    transition:all 0.1s ease-in;
}
.paging > a:hover, .paging > button:hover {
    border-color: #1764c4; 
    background-color: #1764c4; 
    color: #fff;
}
.paging a + a,
.paging button + button {
    margin-left: 7px;
}
.paging .btn-page-start {
    background: no-repeat center center / 16px 15px; 
    background-image: url("../images/sub/first.png");
    border:0px
}
.paging .btn-page-prev {
    background: no-repeat center center / 10px 15px; 
    background-image: url("../images/sub/pre.png");
    border:0px
}
.paging .btn-page-next {
    background: no-repeat center center / 10px 15px; 
    background-image: url("../images/sub/next.png");
    border:0px
}
.paging .btn-page-end {
    background: no-repeat center center / 16px 15px; 
    background-image: url("../images/sub/end.png");
    border:0px
}
.paging .btn-page-start:hover {
    background: no-repeat center center / 16px 15px; 
    background-image: url("../images/sub/first.png");
    
}
.paging .btn-page-prev:hover {
    background: no-repeat center center / 10px 15px; 
    background-image: url("../images/sub/pre.png");
}
.paging .btn-page-next:hover {
    background: no-repeat center center / 10px 15px; 
    background-image: url("../images/sub/next.png");
}
.paging .btn-page-end:hover {
    background: no-repeat center center / 16px 15px; 
    background-image: url("../images/sub/end.png");
}

.paging a.disabled,
.paging button:disabled {cursor:default; opacity: 0.5;}
.paging a.disabled:hover, .paging > button:disabled:hover {
    border-color: transparent; 
    background-color: transparent; 
    color: transparent;
}

.nf-btn:disabled,.nf-btn.disabled {
    cursor:default; 
    border-color: #fff !important; 
    background-color: #fff !important; 
    color: #fff !important;
}

.paging .nav {
    display: flex; 
    align-items: center; 
    justify-content: center; 
