}
.energy-imgBox {
    background: url('../images/sub/bg_level.png') no-repeat 50% 50%;
    width: 178px;
    height: 129px;
    position: relative
}

.energy-arrow {
    content: '';
    position: absolute;
    bottom: 30px;
    left: 79px;
    width: 23px;
    height: 61px;
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(-90deg);
    transform: rotate(-90deg);
    -webkit-transform-origin: 11px 49px;
    transform-origin: 11px 49px;
    -webkit-animation: graph 1s ease;
    animation: graph 1s ease;
}
.energy-arrow.ready {
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(-60deg);
    transform: rotate(-60deg);
}
.energy-arrow.interest {
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(-20deg);
    transform: rotate(-20deg);
}
.energy-arrow.caution {
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(10deg);
    transform: rotate(10deg);
}
.energy-arrow.guard {
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(50deg);
    transform: rotate(50deg);
}
.energy-arrow.caution {
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(10deg);
    transform: rotate(10deg);
}
.energy-arrow.serious {
    background: url('../images/sub/bg_level_arrow.png') 0 0;
    -webkit-transform: rotate(90deg);
    transform: rotate(90deg);
}

